				if err != nil {
					if name != "" && isCoreNotFound(err) {
						return nil, nil
					}
					return nil, err
				}
				if name != "" {
					return toProjectList(out.Project), nil
				}
				return out.Projects, nil
			})
		},
	}
	cmd.Flags().StringVar(&name, "name", "", "filter by exact project name")
