1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/http"
8		"strings"
9	
10		"github.com/entireio/cli/internal/coreapi"
11	)
12	
13	// Control-plane commands reference orgs and projects by their parent ULID in
14	// many places (repo create --project, project create --owner, grant org/project
15	// <id>, …). ULIDs are unfriendly to type, so these refs also accept a human
16	// name: looksLikeULID decides which form was given, and the resolveXRef helpers
17	// turn a name into its ULID. A ULID is always passed straight through with no
18	// network call. A name is resolved by the control plane's O(1), case-insensitive
19	// by-name lookup (the server matches on lower(name) and returns the single match
20	// under the response's singular `org`/`project` field, or 404) — the CLI never
21	// lists everything and filters client-side.
22	
23	// looksLikeULID reports whether s has the shape of a ULID: 26 characters drawn
24	// from Crockford base32 (digits plus uppercase letters, excluding I, L, O, U).
25	// The check is shape-only and case-insensitive on the alphabet; it never hits
26	// the network. A name that happened to be 26 valid base32 characters would be
27	// misread as an id, but real org/project names don't take that form, and the
28	// user can always fall back to the explicit ULID.
29	func looksLikeULID(s string) bool {
30		if len(s) != 26 {
31			return false
32		}
33		for _, r := range strings.ToUpper(s) {
34			switch {
35			case r >= '0' && r <= '9':
36			case r >= 'A' && r <= 'Z' && r != 'I' && r != 'L' && r != 'O' && r != 'U':
37			default:
38				return false
39			}
40		}
41		return true
42	}
43	
44	// isCoreNotFound reports whether err is a control-plane 404. The by-name lookups
45	// (ListOrgs/ListProjects/ListOrgProjects with ?name=) return 404 when nothing
46	// matches; callers turn that into a friendly "no X named" message.
47	func isCoreNotFound(err error) bool {
48		var se *coreapi.ErrorModelStatusCode
49		return errors.As(err, &se) && se.StatusCode == http.StatusNotFound
50	}
51	
52	// resolveOrgRef turns an org reference (ULID or name) into its ULID. A ULID is
53	// returned unchanged; a name is resolved via the server's case-insensitive
54	// by-name lookup.
55	func resolveOrgRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
56		if looksLikeULID(ref) {
57			return ref, nil
58		}
59		out, err := c.ListOrgs(ctx, coreapi.ListOrgsParams{Name: coreapi.NewOptString(ref)})
60		if err != nil {
61			if isCoreNotFound(err) {
62				return "", noOrgNamedErr(ref)
63			}
64			return "", err
65		}
66		org, ok := out.Org.Get()
67		if !ok {
68			return "", noOrgNamedErr(ref)
69		}
70		return org.ID, nil
71	}
72	
73	// resolveAccountRef turns an account reference into its ULID. A ULID passes
74	// through unchanged; otherwise the ref is a provider-qualified handle (e.g.
75	// "github:alice") resolved via the control plane. We support github-backed
76	// user accounts today; other providers will resolve once they exist server-side.
77	func resolveAccountRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
78		if looksLikeULID(ref) {
79			return ref, nil
80		}
81		provider, handle, err := parseQualifiedHandle(ref)
82		if err != nil {
83			return "", err
84		}
85		id, err := c.ResolveHandle(ctx, coreapi.ResolveHandleParams{Provider: provider, Handle: handle})
86		if err != nil {
87			return "", err
88		}
89		// ResolvedIdentity.AccountId is a plain string, so a handle that resolves to
90		// an identity with no backing account would silently forward "" as the owner
91		// ULID and fail later with an opaque server-side create error. Catch it here.
92		if id.AccountId == "" {
93			return "", fmt.Errorf("handle %q resolved to no account", ref)
94		}
95		return id.AccountId, nil
96	}
97	
98	// parseQualifiedHandle splits a provider-qualified handle like "github:alice"
99	// into its provider ("github") and handle ("alice"). Accounts are addressed by
100	// this friendly form; a value with no "provider:" prefix is rejected so the
101	// user gets a clear hint rather than a confusing lookup miss.
102	func parseQualifiedHandle(ref string) (provider, handle string, err error) {
103		provider, handle, ok := strings.Cut(ref, ":")
104		if !ok || provider == "" || handle == "" {
105			return "", "", fmt.Errorf("account %q must be a qualified handle like \"github:alice\" (or a ULID)", ref)
106		}
107		return provider, handle, nil
108	}
109	
110	// resolveProjectRef turns a project reference (ULID or name) into its ULID. A
111	// ULID is returned unchanged; a name is resolved via the server's
